52	/**
53	 * AggregateOperator is used to aggregate values over a set of group by keys.
54	 * Output data will be in the format of [group by key, aggregate result1, ... aggregate resultN]
55	 * When the list of aggregation calls is empty, this class is used to calculate distinct result based on group by keys.
56	 */
57	public class AggregateOperator extends MultiStageOperator {
58	  private static final Logger LOGGER = LoggerFactory.getLogger(AggregateOperator.class);
59	  private static final String EXPLAIN_NAME = "AGGREGATE_OPERATOR";
60	  private static final CountAggregationFunction COUNT_STAR_AGG_FUNCTION =
61	      new CountAggregationFunction(Collections.singletonList(ExpressionContext.forIdentifier("*")), false);
62	
63	  private final MultiStageOperator _input;
64	  private final DataSchema _resultSchema;
65	  private final MultistageAggregationExecutor _aggregationExecutor;
66	  private final MultistageGroupByExecutor _groupByExecutor;
67	  @Nullable
68	  private TransferableBlock _eosBlock;
69	  private final StatMap<StatKey> _statMap = new StatMap<>(StatKey.class);
70	
71	  private boolean _hasConstructedAggregateBlock;
72	
73	  public AggregateOperator(OpChainExecutionContext context, MultiStageOperator input, AggregateNode node) {
74	    super(context);
75	    _input = input;
76	    _resultSchema = node.getDataSchema();
77	
78	    // Initialize the aggregation functions
79	    AggregationFunction<?, ?>[] aggFunctions = getAggFunctions(node.getAggCalls());
80	    int numFunctions = aggFunctions.length;
81	
82	    // Process the filter argument indices
83	    List<Integer> filterArgs = node.getFilterArgs();
84	    int[] filterArgIds = new int[numFunctions];
85	    int maxFilterArgId = -1;
86	    for (int i = 0; i < numFunctions; i++) {
87	      filterArgIds[i] = filterArgs.get(i);
88	      maxFilterArgId = Math.max(maxFilterArgId, filterArgIds[i]);
89	    }
90	
91	    // Initialize the appropriate executor.
92	    List<Integer> groupKeys = node.getGroupKeys();
93	    AggregateNode.AggType aggType = node.getAggType();
94	    // TODO: Allow leaf return final result for non-group-by queries
95	    boolean leafReturnFinalResult = node.isLeafReturnFinalResult();
96	    if (groupKeys.isEmpty()) {
97	      _aggregationExecutor =
98	          new MultistageAggregationExecutor(aggFunctions, filterArgIds, maxFilterArgId, aggType, _resultSchema);
99	      _groupByExecutor = null;
100	    } else {
101	      _groupByExecutor =
102	          new MultistageGroupByExecutor(getGroupKeyIds(groupKeys), aggFunctions, filterArgIds, maxFilterArgId, aggType,
103	              leafReturnFinalResult, _resultSchema, context.getOpChainMetadata(), node.getNodeHint());
104	      _aggregationExecutor = null;
105	    }
106	  }
107	
108	  @Override
109	  public void registerExecution(long time, int numRows) {
110	    _statMap.merge(StatKey.EXECUTION_TIME_MS, time);
111	    _statMap.merge(StatKey.EMITTED_ROWS, numRows);
112	  }
113	
114	  @Override
115	  public Type getOperatorType() {
116	    return Type.AGGREGATE;
117	  }
118	
119	  @Override
120	  protected Logger logger() {
121	    return LOGGER;
122	  }
123	
124	  @Override
125	  public List<MultiStageOperator> getChildOperators() {
126	    return List.of(_input);
127	  }
128	
129	  @Override
130	  public String toExplainString() {
131	    return EXPLAIN_NAME;
132	  }
133	
134	  @Override
135	  protected TransferableBlock getNextBlock() {
136	    if (_hasConstructedAggregateBlock) {
137	      assert _eosBlock != null;
138	      return _eosBlock;
139	    }
140	    TransferableBlock finalBlock = _aggregationExecutor != null ? consumeAggregation() : consumeGroupBy();
141	    // returning upstream error block if finalBlock contains error.
142	    if (finalBlock.isErrorBlock()) {
143	      return finalBlock;
144	    }
145	    assert finalBlock.isSuccessfulEndOfStreamBlock() : "Final block must be EOS block";
146	    _eosBlock = updateEosBlock(finalBlock, _statMap);
147	    return produceAggregatedBlock();
148	  }
149	
150	  private TransferableBlock produceAggregatedBlock() {
151	    _hasConstructedAggregateBlock = true;
152	    if (_aggregationExecutor != null) {
153	      return new TransferableBlock(_aggregationExecutor.getResult(), _resultSchema, DataBlock.Type.ROW);
154	    } else {
155	      List<Object[]> rows = _groupByExecutor.getResult();
156	      if (rows.isEmpty()) {
157	        return _eosBlock;
158	      } else {
159	        TransferableBlock dataBlock = new TransferableBlock(rows, _resultSchema, DataBlock.Type.ROW);
160	        if (_groupByExecutor.isNumGroupsLimitReached()) {
161	          _statMap.merge(StatKey.NUM_GROUPS_LIMIT_REACHED, true);
162	          _input.earlyTerminate();
163	        }
164	        return dataBlock;
165	      }
166	    }
167	  }
168	
169	  /**
170	   * Consumes the input blocks as a group by
171	   *
172	   * @return the last block, which must always be either an error or the end of the stream
173	   */
174	  private TransferableBlock consumeGroupBy() {
175	    TransferableBlock block = _input.nextBlock();
176	    while (block.isDataBlock()) {
177	      _groupByExecutor.processBlock(block);
178	      sampleAndCheckInterruption();
179	      block = _input.nextBlock();
180	    }
181	    return block;
182	  }
