26	/**
27	 * {@code PinotHintOptions} specified the supported hint options by Pinot based a particular type of relation node.
28	 *
29	 * <p>for each {@link RelNode} type we support an option hint name.</p>
30	 * <p>for each option hint name there's a corresponding {@link RelHint} that supported only key-value option stored
31	 * in {@link RelHint#kvOptions}</p>
32	 */
33	public class PinotHintOptions {
34	  private PinotHintOptions() {
35	  }
36	
37	  public static final String AGGREGATE_HINT_OPTIONS = "aggOptions";
38	  public static final String JOIN_HINT_OPTIONS = "joinOptions";
39	  public static final String TABLE_HINT_OPTIONS = "tableOptions";
40	  public static final String WINDOW_HINT_OPTIONS = "windowOptions";
41	
42	  public static class AggregateOptions {
43	    public static final String IS_PARTITIONED_BY_GROUP_BY_KEYS = "is_partitioned_by_group_by_keys";
44	    public static final String IS_LEAF_RETURN_FINAL_RESULT = "is_leaf_return_final_result";
45	    public static final String IS_SKIP_LEAF_STAGE_GROUP_BY = "is_skip_leaf_stage_group_by";
46	    public static final String IS_ENABLE_GROUP_TRIM = "is_enable_group_trim";
47	
48	    public static final String NUM_GROUPS_LIMIT = "num_groups_limit";
49	    public static final String MAX_INITIAL_RESULT_HOLDER_CAPACITY = "max_initial_result_holder_capacity";
50	  }
51	
52	  public static class WindowHintOptions {
53	    /**
54	     * Max rows allowed to cache the rows in window for further processing.
55	     */
56	    public static final String MAX_ROWS_IN_WINDOW = "max_rows_in_window";
57	    /**
58	     * Mode when window overflow happens, supported values: THROW or BREAK.
59	     *   THROW(default): Break window cache build process, and throw exception, no further WINDOW operation performed.
60	     *   BREAK: Break window cache build process, continue to perform WINDOW operation, results might be partial.
61	     */
62	    public static final String WINDOW_OVERFLOW_MODE = "window_overflow_mode";
63	  }
64	
65	  public static class JoinHintOptions {
66	    public static final String JOIN_STRATEGY = "join_strategy";
67	    // "hash" is the default strategy for non-SEMI joins
68	    public static final String HASH_JOIN_STRATEGY = "hash";
69	    // "dynamic_broadcast" is the default strategy for SEMI joins
70	    public static final String DYNAMIC_BROADCAST_JOIN_STRATEGY = "dynamic_broadcast";
71	    // "lookup" can be used when the right table is a dimension table replicated to all workers
72	    public static final String LOOKUP_JOIN_STRATEGY = "lookup";
73	
74	    /**
75	     * Max rows allowed to build the right table hash collection.
76	     */
77	    public static final String MAX_ROWS_IN_JOIN = "max_rows_in_join";
78	
79	    /**
80	     * Mode when join overflow happens, supported values: THROW or BREAK.
81	     *   THROW(default): Break right table build process, and throw exception, no JOIN with left table performed.
82	     *   BREAK: Break right table build process, continue to perform JOIN operation, results might be partial.
83	     */
84	    public static final String JOIN_OVERFLOW_MODE = "join_overflow_mode";
85	
86	    /**
87	     * Indicates that the join operator(s) within a certain selection scope are colocated
88	     */
89	    public static final String IS_COLOCATED_BY_JOIN_KEYS = "is_colocated_by_join_keys";
90	
91	    // TODO: Consider adding a Join implementation with join strategy.
92	    public static boolean useLookupJoinStrategy(Join join) {
93	      return LOOKUP_JOIN_STRATEGY.equalsIgnoreCase(
94	          PinotHintStrategyTable.getHintOption(join.getHints(), PinotHintOptions.JOIN_HINT_OPTIONS,
95	              PinotHintOptions.JoinHintOptions.JOIN_STRATEGY));
96	    }
97	  }
98	
99	  public static class TableHintOptions {
100	    /**
101	     * Indicates how many partitions the table must be partitioned by.
102	     * This must be equal to the partition count of the table in
103	     * {@code tableIndexConfig.segmentPartitionConfig.columnPartitionMap}.
104	     */
105	    public static final String PARTITION_KEY = "partition_key";
106	    /**
107	     * The function to use to partition the table.
108	     * This must be equal to {@code functionName} in {@code tableIndexConfig.segmentPartitionConfig.columnPartitionMap}.
109	     */
110	    public static final String PARTITION_FUNCTION = "partition_function";
111	    /**
112	     * The size of each partition.
113	     * This must be equal to {@code numPartition} in {@code tableIndexConfig.segmentPartitionConfig.columnPartitionMap}.
114	     */
115	    public static final String PARTITION_SIZE = "partition_size";
116	    /**
117	     * The number of workers per partition.
118	     *
119	     * How many threads to use in the following stage after partition is joined.
120	     * When partition info is set, each partition is processed as a separate query in the leaf stage.
121	     */
122	    public static final String PARTITION_PARALLELISM = "partition_parallelism";
123	  }
124	}
