+        // Specialize multi-value column with only one value inside
+        if (numValues == 1) {
+          int dictId = multiValueDictIds[0];
+          if (rawKeys == null) {
+            dictIds[i] = dictId;
+          } else {
+            for (IntArray rawKey : rawKeys) {
+              rawKey._elements[i] = dictId;
+            }
+          }
+        } else {
+          if (rawKeys == null) {
+            rawKeys = new IntArray[numValues];
